import { useCallback, useEffect, useRef, useState, type FormEvent, type ReactNode } from 'react';
import {
  ArrowRight, ArrowUpRight, BellOff, BookOpen, CalendarDays, Check, CheckCircle2,
  ChevronLeft, ChevronRight, CircleHelp, Clock3, Copy, ExternalLink, Flag,
  Flower2, Heart, Leaf, LoaderCircle, LogIn, LogOut, MapPin, MessageCircle,
  MoreHorizontal, Pause, Phone, Play, Plus, Search, Settings2, ShieldCheck,
  SlidersHorizontal, Sprout, Users, X, Send, Ban, KeyRound, Trash2, AlertCircle,
} from 'lucide-react';
import type { User, Group, Message, Detail, Organization, Referral, Block, Report, Invite } from './types';

type Values = Record<string, string | boolean>;
type Field = { key: string; label: string; type?: 'text' | 'password' | 'textarea' | 'select' | 'number' | 'checkbox' | 'datetime-local'; placeholder?: string; help?: string; required?: boolean; min?: number; max?: number; minLength?: number; maxLength?: number; autocomplete?: string; options?: { value: string; label: string }[] };
type ModalSpec = { title: string; description?: string; fields?: Field[]; initial?: Values; content?: ReactNode; submitLabel?: string; danger?: boolean; submit?: (values: Values) => Promise<void> };
type Api = <T = Record<string, unknown>>(path: string, method?: string, body?: unknown) => Promise<T>;
const intensityLabels: Record<string, string> = { low: '아주 가볍게', medium: '가볍게 꾸준히', high: '함께 몰입하기' };
const ageLabels: Record<string, string> = { '13-15': '13–15세', '16-18': '16–18세', staff: '운영 담당자' };
const referralLabels: Record<string, string> = { awaiting_connection: '기관 전송 전 · 운영자 확인 대기', cancelled: '요청 취소됨', accepted: '담당자 확인', completed: '연결 완료' };
const reportLabels: Record<string, string> = { pending: '검토 대기', open: '검토 대기', actioned: '조치 완료', restored: '조치 되돌림', reviewed: '검토 완료', resolved: '처리 완료', dismissed: '종결', dismissed_report: '종결' };
const option = (value: string, label: string) => ({ value, label });
const intensityOptions = [option('low', '아주 가볍게'), option('medium', '가볍게 꾸준히'), option('high', '함께 몰입하기')];
const date = (n: number, withTime = true) => new Intl.DateTimeFormat('ko-KR', { timeZone: 'Asia/Seoul', month: 'numeric', day: 'numeric', ...(withTime ? { hour: '2-digit', minute: '2-digit' } as const : {}) }).format(n);
function initials(s: string) { return Array.from(s || '모')[0]; }
function safeHref(value?: string) { try { const u = new URL(value || ''); return u.protocol === 'https:' || u.protocol === 'http:' ? u.href : '#'; } catch { return '#'; } }
function active(group?: Group | null) { return group?.my_status === 'active' || group?.my_status === 'paused'; }

function Modal({ spec, close }: { spec: ModalSpec; close: () => void }) {
  const ref = useRef<HTMLDialogElement>(null);
  const [values, setValues] = useState<Values>(spec.initial || {});
  const [busy, setBusy] = useState(false), [error, setError] = useState('');
  useEffect(() => { const previous = document.activeElement as HTMLElement | null; const d = ref.current; d?.showModal(); return () => { d?.close(); previous?.focus(); }; }, []);
  return <dialog ref={ref} className="modal" aria-labelledby="modal-title" onCancel={e => { e.preventDefault(); if (!busy) close(); }} onClick={e => { if (e.target === ref.current && !busy) close(); }}>
    <form onSubmit={async e => { e.preventDefault(); if (!spec.submit || busy) return; setBusy(true); setError(''); try { await spec.submit(values); close(); } catch (err) { setError((err as Error).message); } finally { setBusy(false); } }}>
      <div className="modal-head"><div><span className="eyebrow">MOA · 모아</span><h2 id="modal-title">{spec.title}</h2></div><button type="button" className="icon-button" aria-label="닫기" disabled={busy} onClick={close}><X size={20} /></button></div>
      {spec.description && <p className="modal-description">{spec.description}</p>}
      {spec.content}
      <div className="fields">{spec.fields?.map(f => <label key={f.key} className={f.type === 'checkbox' ? 'checkbox-field' : 'field'}>
        {f.type === 'checkbox' ? <><input type="checkbox" checked={!!values[f.key]} required={f.required !== false} onChange={e => setValues({ ...values, [f.key]: e.target.checked })} /><span>{f.label}</span></> : <><span>{f.label}{f.required === false && <small>선택</small>}</span>{f.type === 'textarea' ? <textarea value={String(values[f.key] ?? '')} required={f.required !== false} maxLength={f.maxLength || 1000} placeholder={f.placeholder} onChange={e => setValues({ ...values, [f.key]: e.target.value })} /> : f.type === 'select' ? <select value={String(values[f.key] ?? '')} required={f.required !== false} onChange={e => setValues({ ...values, [f.key]: e.target.value })}><option value="" disabled>선택해 주세요</option>{f.options?.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}</select> : <input type={f.type || 'text'} value={String(values[f.key] ?? '')} required={f.required !== false} min={f.min} max={f.max} minLength={f.minLength} maxLength={f.maxLength || 200} autoComplete={f.autocomplete || 'off'} placeholder={f.placeholder} onChange={e => setValues({ ...values, [f.key]: e.target.value })} />}</>}
        {f.help && <small className="field-help">{f.help}</small>}
      </label>)}</div>
      {error && <div className="error-message" role="alert"><AlertCircle size={17} />{error}</div>}
      {spec.submit && <div className="modal-actions"><button type="button" className="button secondary" disabled={busy} onClick={close}>취소</button><button className={`button ${spec.danger ? 'danger' : ''}`} disabled={busy}>{busy ? <><LoaderCircle className="spin" size={17} />처리 중</> : spec.submitLabel || '저장하기'}</button></div>}
    </form>
  </dialog>;
}

function Auth({ mode, setMode, api, onSuccess, close }: { mode: 'login' | 'register'; setMode: (m: 'login' | 'register') => void; api: Api; onSuccess: (user: User) => void; close: () => void }) {
  const ref = useRef<HTMLDialogElement>(null);
  const [busy, setBusy] = useState(false), [error, setError] = useState('');
  useEffect(() => { const previous = document.activeElement as HTMLElement | null; ref.current?.showModal(); return () => { ref.current?.close(); previous?.focus(); }; }, []);
  async function submit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); if (busy) return;
    const f = new FormData(e.currentTarget); setBusy(true); setError('');
    try {
      const data = { username: String(f.get('username') || '').trim(), password: String(f.get('password') || ''), ...(mode === 'register' ? { nickname: String(f.get('nickname') || '').trim(), invite_code: String(f.get('invite_code') || '').trim(), consent: f.get('consent') === 'on' } : {}) };
      const result = await api<{ user: User }>(`/auth/${mode}`, 'POST', data); onSuccess(result.user); close();
    } catch (err) { setError((err as Error).message); } finally { setBusy(false); }
  }
  return <dialog ref={ref} className="modal auth-modal" aria-labelledby="auth-title" onCancel={e => { e.preventDefault(); if (!busy) close(); }}>
    <button className="icon-button auth-close" type="button" aria-label="닫기" disabled={busy} onClick={close}><X size={20} /></button>
    <div className="auth-brand"><span className="brand-mark"><Sprout size={25} /></span><strong>모아</strong></div>
    <h2 id="auth-title">{mode === 'login' ? '다시 만나서 반가워요.' : '나의 속도로, 시작해요.'}</h2>
    <p className="muted">{mode === 'login' ? '모아 계정으로 이어가세요.' : '기관에서 받은 초대 코드로 또래 모임에 함께해요.'}</p>
    <div className="auth-tabs"><button disabled={busy} className={mode === 'login' ? 'selected' : ''} onClick={() => { setMode('login'); setError(''); }}>로그인</button><button disabled={busy} className={mode === 'register' ? 'selected' : ''} onClick={() => { setMode('register'); setError(''); }}>초대받아 가입</button></div>
    <form key={mode} onSubmit={submit}>
      <div className="fields">
        {mode === 'register' && <label className="field"><span>초대 코드</span><input name="invite_code" required autoComplete="off" maxLength={128} placeholder="담당자에게 받은 코드를 입력해 주세요" /><small className="field-help">기관에서 연령을 확인한 뒤 발급해요. 13세는 법정대리인 동의 확인도 필요해요.</small></label>}
        <label className="field"><span>아이디</span><input name="username" required autoComplete="username" minLength={3} maxLength={32} pattern="[A-Za-z0-9_]+" placeholder="영문, 숫자, 밑줄 3–32자" /></label>
        <label className="field"><span>비밀번호</span><input name="password" type="password" required minLength={mode === 'register' ? 12 : undefined} maxLength={128} autoComplete={mode === 'register' ? 'new-password' : 'current-password'} placeholder={mode === 'register' ? '12자 이상으로 만들어 주세요' : '비밀번호를 입력해 주세요'} /></label>
        {mode === 'register' && <><label className="field"><span>함께할 때 부를 이름</span><input name="nickname" required minLength={2} maxLength={24} autoComplete="nickname" placeholder="실명 대신 편한 닉네임" /></label><details className="privacy-notice"><summary>개인정보 안내 펼쳐 읽기</summary><div><h3>어떤 정보를 저장하나요?</h3><p>가입할 때 아이디, 비밀번호 확인용 해시값, 닉네임, 기관에서 확인한 연령과 초대·동의 기록을 저장해요. 관심사·사는 시군구·편한 시간은 선택해서 적어요. 이용 중 만든 모임과 글, 선택해서 남긴 참여·마음 기록, 차단·신고와 연결 요청도 저장해요.</p><h3>어디에 쓰고 누가 보나요?</h3><p>로그인, 연령대별 모임 추천과 운영, 안전한 이용과 도움 요청 처리를 위해 써요. 닉네임·연령대·글은 모임 안에서 공유되고, 운영 담당자가 필요한 운영 정보와 신고·연결 요청을 확인할 수 있어요. 기관 연결을 위한 연락처는 요청할 때 별도 동의를 받아요. 현재 기관에 자동 전송하지 않아요.</p><h3>탈퇴하면 어떻게 되나요?</h3><p>계정 설정에서 탈퇴할 수 있어요. 로그인 정보·프로필·작성 글은 삭제하거나 익명화하고, 참여·마음 기록과 연결 요청의 연락처·내용은 지워요. 연령·동의 확인과 탈퇴·신고 조치 등 최소 안전 기록은 남을 수 있어요.</p><h3>동의하지 않아도 되나요?</h3><p>동의를 거부할 수 있어요. 다만 계정과 모임 운영에 필요한 정보여서 동의하지 않으면 가입할 수 없어요. 가입하지 않아도 기관 안내는 볼 수 있어요.</p></div></details><label className="checkbox-field"><input name="consent" type="checkbox" required /><span>개인정보 안내를 읽었으며 계정과 모임 운영에 필요한 정보 처리에 동의해요.</span></label></>}
      </div>
      {error && <div className="error-message" role="alert"><AlertCircle size={17} />{error}</div>}
      <button className="button full auth-submit" disabled={busy}>{busy ? <LoaderCircle className="spin" size={17} /> : mode === 'register' ? <Sprout size={17} /> : <LogIn size={17} />}{busy ? '확인하고 있어요' : mode === 'register' ? '모아 시작하기' : '로그인'}</button>
      <p className="auth-note">초대 코드나 계정 이용에 도움이 필요하면 초대한 기관 담당자에게 문의해 주세요.</p>
    </form>
  </dialog>;
}

function Empty({ icon: Icon = Sprout, title, children, action }: { icon?: typeof Sprout; title: string; children: ReactNode; action?: ReactNode }) {
  return <div className="empty"><span className="empty-symbol"><Icon size={29} strokeWidth={1.5} /></span><h3>{title}</h3><p>{children}</p>{action}</div>;
}
function Avatar({ name, own = false }: { name: string; own?: boolean }) { return <span aria-hidden="true" className={`avatar ${own ? 'own' : ''}`}>{initials(name)}</span>; }

export default function App() {
  const [user, setUser] = useState<User | null>(null), [booting, setBooting] = useState(true), [loading, setLoading] = useState(false);
  const [route, setRoute] = useState(window.location.hash.slice(1) || '/');
  const [groups, setGroups] = useState<Group[]>([]), [detail, setDetail] = useState<Detail | null>(null);
  const [organizations, setOrganizations] = useState<Organization[]>([]), [referrals, setReferrals] = useState<Referral[]>([]), [blocks, setBlocks] = useState<Block[]>([]);
  const [reports, setReports] = useState<Report[]>([]), [invites, setInvites] = useState<Invite[]>([]), [adminReferrals, setAdminReferrals] = useState<Referral[]>([]);
  const [authMode, setAuthMode] = useState<'login' | 'register' | null>(null), [modal, setModal] = useState<ModalSpec | null>(null);
  const [message, setMessage] = useState(''), [search, setSearch] = useState(''), [tab, setTab] = useState('chat'), [adminTab, setAdminTab] = useState('reports');
  const [busy, setBusy] = useState(false), [toast, setToast] = useState(''), [pageError, setPageError] = useState(''), [online, setOnline] = useState(navigator.onLine);
  const [freshInvite, setFreshInvite] = useState<{ code: string; expires: number } | null>(null);
  const csrf = useRef(''), clientId = useRef<string | null>(null), messageEnd = useRef<HTMLDivElement>(null);
  const viewKeyRef = useRef(''), requestGeneration = useRef(0);
  const isStaff = user?.role === 'admin' || user?.role === 'moderator';
  const groupId = route.startsWith('/groups/') ? route.split('/')[2] : null;
  const viewKey = `${user?.id || 'anonymous'}:${route}`;
  if (viewKeyRef.current !== viewKey) {
    viewKeyRef.current = viewKey;
    requestGeneration.current += 1;
  }
  const go = (path: string) => { window.location.hash = path; };
  const api = useCallback<Api>(async (path, method = 'GET', body) => {
    const mutation = method !== 'GET';
    if (mutation && !csrf.current) {
      const pre = await fetch('/api/me', { credentials: 'include', cache: 'no-store' });
      const result = await pre.json(); csrf.current = result.csrf_token || '';
    }
    const response = await fetch('/api' + path, { method, credentials: 'include', cache: 'no-store', headers: mutation ? { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf.current } : {}, ...(mutation ? { body: JSON.stringify(body || {}) } : {}) }).catch(() => { throw new Error('서버에 연결하지 못했어요. 인터넷 연결을 확인한 뒤 다시 시도해 주세요.'); });
    let result: Record<string, unknown>;
    try { result = await response.json(); } catch { throw new Error('서버 응답을 읽지 못했어요. 잠시 후 다시 시도해 주세요.'); }
    if (typeof result.csrf_token === 'string') csrf.current = result.csrf_token;
    if (!response.ok) throw new Error(typeof result.error === 'string' ? result.error : '요청을 처리하지 못했어요.');
    return result as never;
  }, []);

  useEffect(() => {
    const nav = () => { setRoute(window.location.hash.slice(1) || '/'); setTab('chat'); setSearch(''); setPageError(''); setMessage(''); clientId.current = null; };
    const net = () => setOnline(navigator.onLine);
    window.addEventListener('hashchange', nav); window.addEventListener('online', net); window.addEventListener('offline', net);
    return () => { window.removeEventListener('hashchange', nav); window.removeEventListener('online', net); window.removeEventListener('offline', net); };
  }, []);
  useEffect(() => { let live = true; (async () => { try { const result = await api<{ user: User | null }>('/me'); if (live) setUser(result.user); const list = await api<{ organizations: Organization[] }>('/organizations'); if (live) setOrganizations(list.organizations); } catch (err) { if (live) setPageError((err as Error).message); } finally { if (live) setBooting(false); } })(); return () => { live = false; }; }, [api]);
  const refresh = useCallback(async () => {
    if (!user) return;
    const requestedView = `${user.id}:${route}`;
    if (viewKeyRef.current !== requestedView) return;
    const generation = ++requestGeneration.current;
    const isCurrent = () => viewKeyRef.current === requestedView && requestGeneration.current === generation;
    const loadAdmin = isStaff && route === '/admin';
    try {
      const [groupList, referralList, blockList, room, reportList, inviteList, adminReferralList] = await Promise.all([
        api<{ groups: Group[] }>('/groups'),
        api<{ referrals: Referral[] }>('/referrals'),
        api<{ blocks: Block[] }>('/blocks'),
        groupId ? api<Detail>(`/groups/${groupId}`) : Promise.resolve(null),
        loadAdmin ? api<{ reports: Report[] }>('/admin/reports') : Promise.resolve(null),
        loadAdmin ? api<{ invites: Invite[] }>('/admin/invites') : Promise.resolve(null),
        loadAdmin ? api<{ referrals: Referral[] }>('/admin/referrals') : Promise.resolve(null),
      ]);
      // Commit one complete response set only while its account, page and generation still match.
      if (!isCurrent()) return;
      setGroups(groupList.groups); setReferrals(referralList.referrals); setBlocks(blockList.blocks);
      setDetail(room);
      if (reportList) setReports(reportList.reports);
      if (inviteList) setInvites(inviteList.invites);
      if (adminReferralList) setAdminReferrals(adminReferralList.referrals);
    } catch (error) {
      if (isCurrent()) throw error;
    }
  }, [api, user?.id, groupId, isStaff, route]);
  useEffect(() => { if (!user) { setGroups([]); setDetail(null); setBlocks([]); setReferrals([]); setReports([]); setInvites([]); setAdminReferrals([]); setFreshInvite(null); return; } let live = true; setLoading(true); setDetail(null); refresh().catch(err => { if (live) setPageError(err.message); }).finally(() => { if (live) setLoading(false); }); return () => { live = false; }; }, [refresh, user?.id]);
  useEffect(() => { if (!user) return; const timer = setInterval(() => { if (document.visibilityState === 'visible' && navigator.onLine) refresh().catch(() => {}); }, groupId ? 6000 : 20000); return () => clearInterval(timer); }, [refresh, user?.id, groupId]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(''), 4500); return () => clearTimeout(timer); }, [toast]);
  useEffect(() => { if (tab === 'chat') messageEnd.current?.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); }, [detail?.messages.length, tab]);

  async function run(work: () => Promise<void>, success?: string) { if (busy) return; setBusy(true); setPageError(''); try { await work(); if (success) setToast(success); } catch (err) { setPageError((err as Error).message); } finally { setBusy(false); } }
  function requireUser() { if (!user) { setAuthMode('login'); return false; } return true; }
  async function mutate(path: string, body: unknown = {}, method = 'POST') { await api(path, method, body); await refresh(); }

  function editProfile() {
    if (!user) return;
    setModal({ title: '나에게 편한 참여', description: '관심사와 시간은 모임을 찾는 데 사용해요. 언제든 바꿔도 괜찮아요.', fields: [
      { key: 'nickname', label: '닉네임', minLength: 2, maxLength: 24 },
      { key: 'district', label: '사는 시·군·구', placeholder: '예: 서울 노원구', required: false, maxLength: 60, help: '주소는 쓰지 않아요. 다른 참여자에게 공개하지 않아요.' },
      { key: 'interests', label: '좋아하거나 해보고 싶은 것', placeholder: '그림, 게임, 책, 코딩', required: false, maxLength: 200, help: '쉼표로 구분해 주세요. 10개까지, 하나당 40자 이내로 적어요.' },
      { key: 'availability', label: '편한 시간', placeholder: '예: 화·목 저녁 7시 이후', required: false, maxLength: 120 },
      { key: 'intensity', label: '함께하고 싶은 정도', type: 'select', options: intensityOptions },
    ], initial: { nickname: user.nickname, district: user.district, interests: user.interests.join(', '), availability: user.availability, intensity: user.intensity || 'low' }, submitLabel: '내 설정 저장', submit: async v => { const result = await api<{ user: User }>('/profile', 'PATCH', { ...v, interests: String(v.interests || '').split(',').map(t => t.trim()).filter(Boolean), participation_mode: 'text' }); setUser(result.user); await refresh(); setToast('편한 참여 방식을 저장했어요.'); } });
  }
  function createGroup() {
    if (!requireUser()) return;
    setModal({ title: '작은 모임 열기', description: '잘하는 것보다 함께해 보고 싶은 것이면 충분해요. 카메라 없이 글로 시작해요.', fields: [
      { key: 'title', label: '모임 이름', placeholder: '예: 그림 한 장, 짧은 안부', maxLength: 80 },
      { key: 'description', label: '어떤 시간을 보내고 싶나요?', type: 'textarea', maxLength: 1000, placeholder: '말이 없는 날은 구경만 해도 괜찮은 모임이에요.' },
      { key: 'topic', label: '관심사 또는 활동 주제', placeholder: '그림, 독서, 보드게임, 검정고시…', maxLength: 80 },
      { key: 'schedule', label: '만나기 편한 시간', placeholder: '예: 토요일 오후 / 편할 때 비동기로', maxLength: 120 },
      { key: 'intensity', label: '활동의 정도', type: 'select', options: intensityOptions },
      { key: 'capacity', label: '함께할 또래 수', type: 'select', options: [option('3', '3명'), option('4', '4명')] },
      ...(isStaff ? [{ key: 'age_group', label: '참여 연령대', type: 'select' as const, options: [option('13-15', '13–15세'), option('16-18', '16–18세')] }] : []),
    ], initial: { intensity: 'low', capacity: '4', ...(isStaff ? { age_group: '13-15' } : {}) }, content: <div className="gentle-note"><Leaf size={18} /><p>참여를 재촉하지 않아요. 누구나 잠시 쉬거나, 이유 없이 나갈 수 있어요.</p></div>, submitLabel: '모임 만들기', submit: async v => { const result = await api<{ group: Group }>('/groups', 'POST', { ...v, capacity: Number(v.capacity), mode: 'text' }); await refresh(); go(`/groups/${result.group.id}`); setToast('새로운 모임을 열었어요.'); } });
  }
  function leaveGroup(g: Group) {
    setModal({ title: '이 모임에서 나갈까요?', description: '이유를 적지 않아도 괜찮아요. 남은 사람들은 자신의 속도로 모임을 이어갈 수 있어요.', content: <p className="modal-description">작성한 메시지는 모임에 남아요. 계정의 전체 정보 삭제는 내 설정에서 할 수 있어요.</p>, submitLabel: '모임 나가기', submit: async () => { await api(`/groups/${g.id}/leave`, 'POST', {}); setDetail(null); go('/my'); setToast('모임에서 나왔어요.'); } });
  }
  function report(target?: { id: string; nickname: string }, item?: Message) {
    if (!detail) return;
    setModal({ title: '운영 담당자에게 알려주세요', description: '신고 내용과 신고자는 다른 참여자에게 공개하지 않아요. 한 사람의 요청도 확인해요.', fields: [
      { key: 'category', label: '어떤 일이 있었나요?', type: 'select', options: ['괴롭힘·비하', '개인정보 요구', '불편한 연락', '유해한 내용', '기타'].map(x => option(x, x)) },
      { key: 'reason', label: '확인할 내용', type: 'textarea', maxLength: 1000, placeholder: '어떤 점이 불편했는지 알려주세요.' },
    ], content: item ? <blockquote className="report-quote">{item.body}</blockquote> : <p className="modal-description">대상: {target?.nickname}</p>, submitLabel: '신고 접수', submit: async v => { await api('/reports', 'POST', { ...v, group_id: detail.group.id, ...(item ? { message_id: item.id } : {}), target_id: item?.user_id || target?.id }); setToast('운영 담당자에게 신고를 접수했어요.'); } });
  }
  function blockPerson(id: string, nickname: string) { setModal({ title: `${nickname}님을 차단할까요?`, description: '이 사람과 다시 매칭하지 않고 메시지를 보이지 않게 해요. 내 설정에서 차단을 해제할 수 있어요.', submitLabel: '차단하기', submit: async () => { await mutate('/blocks', { target_id: id }); setToast('차단했어요.'); } }); }
  function addSession() { if (!detail) return; setModal({ title: '다음 만남 제안하기', description: '참여는 선택이에요. 참석하지 않아도 불이익이 없어요.', fields: [ { key: 'title', label: '만남 이름', maxLength: 80, placeholder: '예: 짧게 안부 나누기' }, { key: 'starts_at', label: '만날 날짜와 시간', type: 'datetime-local', help: '한국 시간으로 입력해 주세요.' }, { key: 'duration_minutes', label: '함께할 시간', type: 'select', options: [15, 30, 45, 60].map(n => option(String(n), `${n}분`)) } ], initial: { duration_minutes: '30' }, submitLabel: '일정 만들기', submit: async v => { const starts_at = new Date(String(v.starts_at) + ':00+09:00').getTime(); if (!Number.isFinite(starts_at)) throw new Error('날짜와 시간을 확인해 주세요.'); await mutate(`/groups/${detail.group.id}/sessions`, { title: v.title, starts_at, duration_minutes: Number(v.duration_minutes) }); setToast('만남 일정을 만들었어요.'); } }); }
  function feedback() { if (!detail) return; setModal({ title: '오늘의 작은 돌아보기', description: '답하지 않아도 괜찮아요. 응답은 다른 참여자에게 공개하지 않아요.', fields: [ { key: 'comfort', label: '오늘 함께한 시간은 얼마나 편했나요?', type: 'select', options: [1,2,3,4,5].map(n => option(String(n), `${n} · ${['많이 불편했어요','조금 불편했어요','보통이에요','조금 편했어요','아주 편했어요'][n-1]}`)) }, { key: 'return_intent', label: '다음에도 함께하고 싶나요?', type: 'select', options: [1,2,3,4,5].map(n => option(String(n), `${n} · ${['쉬고 싶어요','아직 잘 모르겠어요','보통이에요','조금 함께하고 싶어요','다시 함께하고 싶어요'][n-1]}`)) }, { key: 'note', label: '남기고 싶은 말', type: 'textarea', required: false, maxLength: 500 } ], submitLabel: '내 마음 남기기', submit: async v => { await api('/checkins', 'POST', { ...v, group_id: detail.group.id, comfort: Number(v.comfort), return_intent: Number(v.return_intent) }); setToast('마음을 남겼어요.'); } }); }
  function requestReferral(org: Organization) {
    if (!requireUser()) return;
    setModal({ title: '연결 도움 요청하기', description: `${org.name}에 관심이 있다는 요청을 모아 운영 담당자에게 남겨요.`, content: <div className="gentle-note"><CircleHelp size={18} /><p><strong>아직 기관에 전송되거나 예약되지 않아요.</strong><br />연계 가능 여부를 운영 담당자가 확인할 때까지 기다려 주세요. 바로 문의하려면 기관의 공식 연락처를 이용할 수 있어요.</p></div>, fields: [ { key: 'contact', label: '연락받을 방법', placeholder: '연락 가능한 이메일 또는 전화번호', maxLength: 200 }, { key: 'note', label: '도움받고 싶은 내용', type: 'textarea', required: false, maxLength: 1000, placeholder: '예: 처음 방문하기 전에 문자로 안내받고 싶어요.' }, { key: 'consent', label: '선택한 기관, 닉네임, 연락처, 요청 내용을 모아 운영 담당자가 확인하는 데 동의해요. 기관 전송은 아직 진행되지 않으며 요청을 취소할 수 있어요.', type: 'checkbox' } ], submitLabel: '운영자 확인 요청', submit: async v => { await mutate('/referrals', { ...v, organization_id: org.id, consent: v.consent === true }); setToast('기관 전송 전 확인 대기로 저장했어요.'); } });
  }
  function reviewReport(r: Report) {
    const options = r.status === 'open'
      ? [option('dismiss', '조치 없이 종결'), ...(r.message_id ? [option('hide_message', '메시지 숨김')] : []), ...(r.target_id ? [option('restrict_user', '이 모임 참여 제한')] : [])]
      : r.status === 'actioned' ? [option('restore', '조치 되돌리기')] : [];
    const canReview = options.length > 0;
    setModal({
      title: canReview ? '신고 내용 검토' : '신고 내용 보기', description: `${r.group_title} · ${r.category} · ${reportLabels[r.status] || r.status}`,
      content: <div className="review-context"><p>{r.reason}</p>{r.message_body && <blockquote>{r.message_body}</blockquote>}{!canReview && <p>이 신고는 검토가 끝났어요. 내용을 확인할 수 있어요.</p>}</div>,
      fields: canReview ? [{ key: 'decision', label: '검토 결과', type: 'select', options }, { key: 'note', label: '판단 근거와 조치 이유', type: 'textarea', maxLength: 1000 }] : [],
      initial: r.status === 'actioned' ? { decision: 'restore' } : {},
      submitLabel: '검토 기록 저장',
      ...(canReview ? { submit: async (v: Values) => { await mutate(`/admin/reports/${r.id}/review`, v); setToast('검토와 조치를 기록했어요.'); } } : {}),
    });
  }
  function inviteUser() { setModal({ title: '참여 초대 만들기', description: '실제로 연령과 필요한 동의를 확인한 청소년에게만 발급하세요. 한 번 사용할 수 있는 코드예요.', fields: [ { key: 'label', label: '내부 관리용 이름', maxLength: 60, placeholder: '이름 대신 기관 내 식별번호 사용 권장' }, { key: 'age', label: '확인한 만 나이', type: 'select', options: [13,14,15,16,17,18].map(n => option(String(n), `${n}세`)) }, { key: 'age_verified', label: '기관의 절차에 따라 대상자의 연령을 실제로 확인했습니다.', type: 'checkbox' }, { key: 'guardian_verified', label: '만 13세인 경우 법정대리인의 동의와 동의 여부를 확인했습니다.', type: 'checkbox', required: false } ], submitLabel: '초대 코드 발급', submit: async v => { const result = await api<{ invite_code: string; expires_at: number }>('/admin/invites', 'POST', { ...v, age: Number(v.age), guardian_verified: v.guardian_verified === true, age_verified: v.age_verified === true }); setFreshInvite({ code: result.invite_code, expires: result.expires_at }); await refresh(); } }); }

  function GroupCard({ group: g, index = 0 }: { group: Group; index?: number }) {
    const joined = active(g), paused = g.my_status === 'paused';
    const reasons = isStaff ? ['운영 담당자 열람'] : !user?.interests.length ? [g.reasons?.[0] || '같은 연령대', '관심사 설정 전'] : g.reasons?.length ? g.reasons : ['참여 가능한 연령대'];
    return <article className={`group-card tone-${index % 3}`}>
      <div className="group-art"><div className="group-motif"><Flower2 size={60} strokeWidth={1.1} /><span /></div><span className="age-chip">{ageLabels[g.age_group] || g.age_group}</span><span className="mode-chip"><MessageCircle size={13} />글로 함께</span></div>
      <div className="group-card-body"><div className="tag-line"><span>{g.topic}</span>{paused && <span className="pause-tag"><Pause size={11} />쉬는 중</span>}</div><h3>{g.title}</h3><p className="group-description">{g.description}</p><div className="group-facts"><span><Clock3 size={14} />{g.schedule || '편한 시간을 함께 정해요'}</span><span><Leaf size={14} />{intensityLabels[g.intensity] || g.intensity}</span></div>
        {!joined && <div className="match-reason"><Check size={13} />{reasons.slice(0, 2).join(' · ')}</div>}
        <div className="group-card-bottom"><span><Users size={15} />{g.member_count}/{g.capacity}명</span><button className={joined ? 'text-button' : 'button small'} disabled={busy || (!joined && !isStaff && (g.status === 'archived' || g.member_count >= g.capacity))} onClick={() => { if (!requireUser()) return; if (joined || isStaff) go(`/groups/${g.id}`); else setModal({ title: `${g.title}에 함께할까요?`, description: '글로 인사하거나 잠시 지켜봐도 괜찮아요. 원할 때 쉬거나 나갈 수 있어요.', submitLabel: '함께하기', submit: async () => { await api(`/groups/${g.id}/join`, 'POST', {}); await refresh(); go(`/groups/${g.id}`); } }); }}>{joined ? '모임 열기' : isStaff ? '살펴보기' : g.status === 'archived' ? '마무리된 모임' : g.member_count >= g.capacity ? '정원이 찼어요' : '함께하기'}<ArrowRight size={15} /></button></div>
      </div>
    </article>;
  }

  function directory() { return <><div className="page-heading"><div><span className="eyebrow">A LITTLE HELP</span><h1>다음 연결도, 천천히.</h1><p>혼자 알아보기 어려울 때, 청소년을 위한 기관을 살펴보세요.</p></div><span className="outlined-badge"><ShieldCheck size={15} />공식 안내</span></div><div className="help-intro"><div className="round-icon"><Heart size={23} /></div><div><h3>온라인으로 먼저 물어봐도 괜찮아요.</h3><p>청소년상담 1388에서 내 상황에 맞는 도움을 안내받을 수 있어요. 모아의 목록은 공식 안내이며, 협약이나 방문 예약을 뜻하지 않아요.</p></div><a className="button secondary" href="https://www.1388.go.kr/" target="_blank" rel="noopener noreferrer">1388 알아보기<ExternalLink size={15} /></a></div><div className="organization-grid">{organizations.map(org => <article className="organization-card" key={org.id}><div className="row spaced"><span className="round-icon small"><MapPin size={21} /></span><span className="chip">공식 정보</span></div><h3>{org.name}</h3><p>{org.description}</p><div className="organization-details"><span><MapPin size={14} />{org.region}</span>{org.phone && <span><Phone size={14} />{org.phone}</span>}{org.min_age != null && <span><Users size={14} />안내 대상 {org.min_age}–{org.max_age}세</span>}</div><small className="muted">현재 모집·이용 조건은 기관에서 확인해 주세요.</small><div className="organization-actions"><a className="text-button" href={safeHref(org.website)} target="_blank" rel="noopener noreferrer">공식 사이트<ArrowUpRight size={15} /></a><button className="button secondary small" onClick={() => requestReferral(org)}>연결 도움 요청</button></div><a className="source-link" href={safeHref(org.source_url)} target="_blank" rel="noopener noreferrer">정보 출처 확인<ExternalLink size={11} /></a></article>)}</div>{!organizations.length && <div className="panel"><Empty icon={MapPin} title="기관 정보를 준비하고 있어요">1388 공식 사이트에서 가까운 청소년 지원기관을 찾아볼 수 있어요.</Empty></div>}{user && <section className="section-space"><div className="section-heading"><div><h2>내가 남긴 연결 요청</h2><p>전송 전 요청은 언제든 취소할 수 있어요.</p></div></div><div className="panel">{referrals.length ? referrals.map(r => <div key={r.id} className="request-row"><div><span className="chip neutral">{referralLabels[r.status] || r.status}</span><h3>{r.organization_name}</h3><p>{date(r.created_at)}{r.note ? ` · ${r.note}` : ''}</p></div>{r.status === 'awaiting_connection' && <button className="text-button muted" disabled={busy} onClick={() => run(() => mutate(`/referrals/${r.id}/cancel`), '연결 요청을 취소했어요.')}>요청 취소</button>}</div>) : <Empty icon={Heart} title="필요할 때 요청해 주세요">남긴 요청은 이곳에서 확인할 수 있어요.</Empty>}</div></section>}</>; }

  function groupView() {
    if (!detail || detail.group.id !== groupId) return <div className="panel"><Empty title={loading ? '모임을 열고 있어요' : '모임에 들어갈 수 없어요'}>{loading ? '잠시만 기다려 주세요.' : '참여 상태를 확인하거나 나의 모임으로 돌아가 주세요.'}<a className="text-button" href="#/my">나의 모임<ArrowRight size={15} /></a></Empty></div>;
    const g = detail.group, joined = active(g), paused = g.my_status === 'paused';
    const canWrite = joined && g.status !== 'archived';
    return <><a className="back-link" href="#/my"><ChevronLeft size={15} />나의 모임</a><section className="group-hero"><div><div className="row wrap"><span className="chip">{g.topic}</span><span className="muted small-text">{ageLabels[g.age_group]} · 글로 함께</span>{paused && <span className="chip warm">쉬는 중</span>}</div><h1>{g.title}</h1><p>{g.description}</p><div className="row wrap group-hero-meta"><span><Users size={15} />{g.member_count}/{g.capacity}명</span><span><Clock3 size={15} />{g.schedule}</span><span><Leaf size={15} />{intensityLabels[g.intensity]}</span></div></div><div className="group-hero-actions">{isStaff && !joined && g.status !== 'archived' && <button className="button secondary small" disabled={busy} onClick={() => setModal({ title: '운영 담당자로 함께할까요?', description: '참여하면 명단에 운영 담당자로 표시되고 대화와 일정 제안을 할 수 있어요. 또래 정원에는 포함되지 않아요.', submitLabel: '운영 담당자로 참여', submit: async () => { await mutate(`/groups/${g.id}/join`); setToast('운영 담당자로 함께하고 있어요.'); } })}><Plus size={14} />운영 담당자로 참여</button>}{joined && <><button className="button secondary small" disabled={busy} onClick={() => run(() => mutate(`/groups/${g.id}/pause`, { paused: !paused }), paused ? '편할 때 다시 함께해요.' : '잠시 쉬어가요. 자리는 그대로예요.')}>{paused ? <Play size={14} /> : <Pause size={14} />}{paused ? '다시 함께하기' : '잠시 쉬기'}</button><button className="text-button muted" onClick={() => leaveGroup(g)}><LogOut size={14} />모임 나가기</button></>}</div></section><div className="group-tabs" role="tablist" aria-label="모임 내용">{[['chat','함께 나누기',MessageCircle],['schedule','만남 일정',CalendarDays],['members','함께하는 사람',Users]].map(([id,label,Icon]) => { const I = Icon as typeof Users; return <button key={id as string} role="tab" aria-selected={tab === id} className={tab === id ? 'selected' : ''} onClick={() => setTab(id as string)}><I size={17} />{label as string}</button>; })}</div>
      {tab === 'chat' ? <div className="conversation-layout"><section className="panel conversation"><div className="conversation-head"><div><h2>오늘은 어떤 이야기를 나눌까요?</h2><p>대답을 서두르지 않아도 괜찮아요.</p></div><span className="chip neutral"><MessageCircle size={12} />텍스트 모임</span></div><div className="messages" aria-live="polite" aria-relevant="additions">{detail.messages.length ? detail.messages.map(m => <article key={m.id} className={`message ${m.user_id === user?.id ? 'mine' : ''}`}><Avatar name={m.nickname} own={m.user_id === user?.id} /><div className="message-content"><div className="message-meta"><strong>{m.nickname}</strong><time dateTime={new Date(m.created_at).toISOString()}>{date(m.created_at)}</time>{m.user_id !== user?.id && !m.hidden && <button className="icon-button tiny-icon" title="메시지 신고" aria-label={`${m.nickname}님의 메시지 신고`} onClick={() => report(undefined, m)}><Flag size={12} /></button>}</div><p className={m.hidden ? 'hidden-message' : ''}>{m.body}</p></div></article>) : <Empty icon={MessageCircle} title="첫 인사도, 짧게 괜찮아요">좋아하는 것 하나나 오늘의 기분을 남겨 보세요.</Empty>}<div ref={messageEnd} /></div>{canWrite ? <form className="composer" onSubmit={e => { e.preventDefault(); if (!message.trim() || busy) return; const body = message.trim(); clientId.current ||= crypto.randomUUID(); run(async () => { await api(`/groups/${g.id}/messages`, 'POST', { body, client_id: clientId.current }); setMessage(''); clientId.current = null; await refresh(); }); }}><label className="sr-only" htmlFor="message-body">모임에 남길 이야기</label><textarea id="message-body" value={message} maxLength={1000} placeholder="짧은 안부를 남겨 주세요…" onChange={e => { setMessage(e.target.value); clientId.current = null; }} /><div className="row spaced"><small>{message.length}/1000 · 모임과 운영 담당자에게만 보여요</small><button className="button small" disabled={busy || !online || !message.trim()}><Send size={15} />보내기</button></div></form> : <p className="composer-closed">{g.status === 'archived' ? '마무리된 모임이에요.' : '대화를 남기려면 운영 담당자로 참여해 주세요. 열람만 해도 괜찮아요.'}</p>}</section><aside className="conversation-aside"><div className="aside-note"><span className="round-icon"><Leaf size={23} /></span><h3>함께하는 우리의 약속</h3><p>말이 적은 날도, 잠깐 쉬는 날도 있어요. 각자의 속도를 존중해요.</p><ul><li>개인 연락처를 요구하지 않기</li><li>허락 없이 글을 옮기지 않기</li><li>불편한 일은 담당자에게 알리기</li></ul>{joined && <button className="text-button" onClick={feedback}>오늘의 마음 남기기<ArrowRight size={14} /></button>}</div><div className="aside-help"><Heart size={20} /><h3>다음 연결이 필요할 때</h3><p>가까운 청소년 지원기관부터 천천히 알아봐요.</p><a className="text-button" href="#/help">연결 도움 살펴보기<ArrowUpRight size={14} /></a></div></aside></div> : tab === 'schedule' ? <section className="panel section-panel"><div className="section-heading"><div><h2>함께 정하는 다음 시간</h2><p>일정 참여와 참여 기록은 모두 선택이에요.</p></div>{canWrite && <button className="button small" onClick={addSession}><Plus size={16} />만남 제안</button>}</div>{detail.sessions.length ? <div className="session-list">{detail.sessions.map(s => { const canCheck = Date.now() >= s.starts_at - 900000 && Date.now() <= s.starts_at + (s.duration_minutes + 60) * 60000; return <div className="session-row" key={s.id}><span className="session-date"><CalendarDays size={23} /><strong>{date(s.starts_at, false)}</strong></span><div><h3>{s.title}</h3><p>{date(s.starts_at)} · {s.duration_minutes}분</p><small className="muted">한국 시간</small></div>{joined && <button className="button secondary small" disabled={busy || !!s.checked_in || !canCheck} onClick={() => run(() => mutate(`/sessions/${s.id}/checkin`), '나의 참여를 기록했어요.')}>{s.checked_in ? <><Check size={15} />참여 기록됨</> : canCheck ? '참여했어요' : '만남 시간에 기록'}</button>}</div>; })}</div> : <Empty icon={CalendarDays} title="아직 정해진 만남이 없어요">함께하기 편한 짧은 시간을 제안해 보세요.</Empty>}</section> : <section className="panel section-panel"><div className="section-heading"><div><h2>함께하는 사람들</h2><p>서로에게 보여주는 이름과 연령대만 표시해요.</p></div></div><div className="member-list">{detail.members.map(m => <div className="member-row" key={m.id}><Avatar name={m.nickname} /><div className="member-name"><h3>{m.nickname}{m.id === user?.id && <span className="me-label">나</span>}</h3><p>{ageLabels[m.age_group] || m.age_group}</p></div>{m.id !== user?.id && joined && <div className="member-actions"><button className="text-button muted" onClick={() => blockPerson(m.id, m.nickname)}><Ban size={14} />차단</button><button className="icon-button" aria-label={`${m.nickname}님 관련 신고`} onClick={() => report(m)}><Flag size={16} /></button></div>}</div>)}</div></section>}
    </>;
  }

  function settings() { return <><div className="page-heading"><div><span className="eyebrow">MY PACE</span><h1>나에게 맞는 속도</h1><p>참여 방식과 계정은 내가 정해요.</p></div></div><div className="settings-grid"><section className="panel section-panel"><div className="profile-summary"><Avatar name={user!.nickname} own /><div><h2>{user!.nickname}</h2><p>{ageLabels[user!.age_group]} · {user!.role === 'participant' ? '함께하는 사람' : '운영 담당자'}</p></div><button className="button secondary small" onClick={editProfile}>참여 설정</button></div><dl className="profile-values"><div><dt>관심사</dt><dd>{user!.interests.length ? user!.interests.map(t => <span className="chip" key={t}>{t}</span>) : '아직 정하지 않았어요'}</dd></div><div><dt>편한 시간</dt><dd>{user!.availability || '함께 정할래요'}</dd></div><div><dt>활동 정도</dt><dd>{intensityLabels[user!.intensity] || '아주 가볍게'}</dd></div><div><dt>사는 지역</dt><dd>{user!.district || '입력하지 않았어요'}<small>다른 참여자에게 공개하지 않아요</small></dd></div></dl></section><section className="panel section-panel"><h2>계정 관리</h2><div className="settings-links"><button onClick={() => setModal({ title: '비밀번호 변경', description: '변경하면 다른 기기에 로그인된 계정은 로그아웃돼요.', fields: [ { key: 'current_password', label: '현재 비밀번호', type: 'password', maxLength: 128, autocomplete: 'current-password' }, { key: 'new_password', label: '새 비밀번호', type: 'password', minLength: 12, maxLength: 128, autocomplete: 'new-password', help: '12자 이상으로 만들어 주세요.' } ], submitLabel: '비밀번호 변경', submit: async v => { await api('/auth/password', 'POST', v); setToast('비밀번호를 변경했어요.'); } })}><KeyRound size={18} /><span>비밀번호 바꾸기</span><ChevronRight size={16} /></button><button onClick={() => run(async () => { await api('/auth/logout', 'POST', {}); setUser(null); setDetail(null); setGroups([]); setMessage(''); setReports([]); setInvites([]); setAdminReferrals([]); go('/'); }, '로그아웃했어요.')}><LogOut size={18} /><span>로그아웃</span><ChevronRight size={16} /></button><button className="danger-text" onClick={() => setModal({ title: '계정을 삭제할까요?', description: '이 작업은 되돌릴 수 없어요. 프로필과 작성 메시지를 익명화하고 더 이상 로그인할 수 없게 해요. 안전 조치에 필요한 최소 기록은 남을 수 있어요.', fields: [{ key: 'password', label: '비밀번호 확인', type: 'password', maxLength: 128, autocomplete: 'current-password' }], submitLabel: '계정 삭제', danger: true, submit: async v => { await api('/account', 'DELETE', v); csrf.current = ''; setUser(null); setDetail(null); setMessage(''); go('/'); setToast('계정을 삭제했어요.'); } })}><Trash2 size={18} /><span>계정과 내 정보 삭제</span><ChevronRight size={16} /></button></div></section></div><section className="panel section-panel section-space"><div className="section-heading"><div><h2>차단한 사람</h2><p>차단 해제도 내가 선택해요.</p></div></div>{blocks.length ? blocks.map(b => <div className="member-row" key={b.target_id}><Avatar name={b.nickname} /><div className="member-name"><h3>{b.nickname}</h3><p>{date(b.created_at, false)} 차단</p></div><button className="text-button" disabled={busy} onClick={() => run(() => mutate(`/blocks/${b.target_id}`, {}, 'DELETE'), '차단을 해제했어요.')}>차단 해제</button></div>) : <p className="quiet-empty">차단한 사람이 없어요.</p>}</section></>; }

  function admin() { return <><div className="page-heading"><div><span className="eyebrow">CARE DESK</span><h1>운영 담당자 공간</h1><p>필요한 요청을 확인하고, 판단과 조치를 기록합니다.</p></div><button className="button" onClick={inviteUser}><Plus size={17} />참여 초대</button></div>{freshInvite && <section className="invite-result"><div className="row spaced"><h3>새 초대 코드</h3><button className="icon-button" aria-label="초대 코드 닫기" onClick={() => setFreshInvite(null)}><X size={17} /></button></div><p>이 코드는 지금 한 번만 표시됩니다. 대상자에게 안전하게 전달하세요.</p><div className="row"><input value={freshInvite.code} readOnly aria-label="발급한 초대 코드" onFocus={e => e.currentTarget.select()} /><button className="button secondary small" onClick={async () => { try { await navigator.clipboard.writeText(freshInvite.code); setToast('초대 코드를 복사했어요.'); } catch { setToast('코드를 선택해 직접 복사해 주세요.'); } }}><Copy size={16} />복사</button></div><small>사용기한: {date(freshInvite.expires)}</small></section>}<div className="group-tabs" role="tablist" aria-label="운영 메뉴">{[['reports','신고 검토',Flag],['referrals','연결 요청',Heart],['invites','초대 관리',Users]].map(([id,label,Icon]) => { const I = Icon as typeof Users; return <button key={id as string} role="tab" aria-selected={adminTab === id} className={adminTab === id ? 'selected' : ''} onClick={() => setAdminTab(id as string)}><I size={17} />{label as string}</button>; })}</div><section className="panel section-panel">{adminTab === 'reports' ? <>{reports.length ? reports.map(r => <div className="admin-record" key={r.id}><div className="row spaced"><span className="chip neutral">{reportLabels[r.status] || r.status}</span><time>{date(r.created_at)}</time></div><h3>{r.category} · {r.group_title}</h3><p>{r.reason}</p>{r.target_name && <small>관련 참여자: {r.target_name}</small>}<button className="button secondary small" onClick={() => reviewReport(r)}>{r.status === 'open' || r.status === 'actioned' ? '내용 검토' : '내용 보기'}<ArrowRight size={14} /></button></div>) : <Empty icon={ShieldCheck} title="검토할 신고가 없습니다">새 신고가 접수되면 이곳에 표시됩니다.</Empty>}</> : adminTab === 'referrals' ? <><div className="gentle-note"><CircleHelp size={19} /><p>이 목록은 내부 확인 요청입니다. 기관에 자동 전송되지 않으며, 기관 예약이나 연결 완료를 뜻하지 않습니다.</p></div>{adminReferrals.length ? adminReferrals.map(r => <div className="admin-record" key={r.id}><div className="row spaced"><span className="chip neutral">{referralLabels[r.status] || r.status}</span><time>{date(r.created_at)}</time></div><h3>{r.nickname || r.applicant_nickname || '참여자'} · {r.organization_name}</h3><p>{r.note || '추가 내용 없음'}</p>{r.contact && <p className="private-contact">연락 방법: {r.contact}</p>}</div>) : <Empty icon={Heart} title="아직 연결 요청이 없습니다">참여자가 동의하고 남긴 요청만 확인할 수 있습니다.</Empty>}</> : <>{invites.length ? invites.map(i => <div className="invite-row" key={i.id}><div><h3>{i.label}</h3><p>{i.age}세 · {ageLabels[i.age_group]}{i.guardian_verified ? ' · 법정대리인 동의 확인' : ''}</p><small>사용기한 {date(i.expires_at)}</small></div><span className="chip neutral">{i.used ? '사용됨' : i.revoked_at ? '취소됨' : i.expires_at < Date.now() ? '만료됨' : '사용 전'}</span>{!i.used && !i.revoked_at && i.expires_at > Date.now() && <button className="text-button muted" disabled={busy} onClick={() => run(() => mutate(`/admin/invites/${i.id}/revoke`), '초대를 취소했어요.')}>초대 취소</button>}</div>) : <Empty icon={Users} title="발급한 초대가 없습니다">기관에서 연령과 필요한 동의를 확인한 뒤 초대하세요.</Empty>}</>}</section></>; }

  const myGroups = groups.filter(active);
  const visibleGroups = (route === '/my' ? myGroups : groups.filter(g => g.status !== 'archived')).filter(g => `${g.title} ${g.topic} ${g.description}`.toLowerCase().includes(search.toLowerCase())).sort((a, b) => (route === '/my' ? 0 : (b.match_score || 0) - (a.match_score || 0)) || b.created_at - a.created_at || a.id.localeCompare(b.id));
  return <div className="app"><a className="skip-link" href="#main" onClick={e => { e.preventDefault(); document.getElementById('main')?.focus(); }}>본문으로 바로가기</a><header className="header"><div className="header-inner"><a className="brand" href="#/" aria-label="모아 홈"><span className="brand-mark"><Sprout size={25} /></span><strong>모아</strong><span className="brand-caption">나의 속도로 함께</span></a><nav aria-label="주 메뉴"><a className={route === '/' || route === '/explore' ? 'current' : ''} href={user ? '#/explore' : '#/'}>모임 찾기</a><a className={route === '/my' || groupId ? 'current' : ''} href="#/my" onClick={e => { if (!requireUser()) e.preventDefault(); }}>나의 모임</a><a className={route === '/help' ? 'current' : ''} href="#/help">연결 도움</a>{isStaff && <a className={route === '/admin' ? 'current' : ''} href="#/admin">운영 공간</a>}</nav><div className="header-actions">{user ? <button className="profile-button" onClick={() => go('/settings')} aria-label="내 설정"><Avatar name={user.nickname} own /><span>{user.nickname}</span><ChevronRight size={13} /></button> : <button className="button small" disabled={booting} onClick={() => setAuthMode('login')}>로그인<ArrowUpRight size={15} /></button>}</div></div></header>{!online && <div className="offline-banner"><AlertCircle size={16} />인터넷 연결이 잠시 끊겼어요. 연결된 뒤 다시 보내 주세요.</div>}<main id="main" tabIndex={-1} className="main">
      {pageError && <div className="page-error" role="alert"><AlertCircle size={19} /><span>{pageError}</span><button className="text-button" onClick={() => run(refresh)}>다시 시도</button><button className="icon-button" aria-label="오류 닫기" onClick={() => setPageError('')}><X size={16} /></button></div>}
      {booting ? <div className="initial-loading"><LoaderCircle className="spin" size={30} /><p>모아를 준비하고 있어요.</p></div> : route === '/help' ? directory() : user && route === '/settings' ? settings() : user && isStaff && route === '/admin' ? admin() : user && groupId ? groupView() : !user ? <>
        <section className="landing-hero"><div className="landing-copy"><span className="hero-kicker"><span />조금씩, 우리답게</span><h1>연결은,<br /><em>나의 속도로.</em></h1><p>말이 적은 날도, 함께하고 싶은 날도.<br />관심사가 비슷한 또래와<br className="mobile-break" /> 작은 시간부터 나눠요.</p><div className="hero-buttons"><button className="button" onClick={() => setAuthMode('register')}>초대받아 시작하기<ArrowRight size={18} /></button><a className="text-button" href="#/help">먼저 도움 알아보기<ArrowUpRight size={15} /></a></div><div className="hero-note"><ShieldCheck size={16} /><span>13–18세 또래 · 카메라 없이 · 쉬어도 괜찮게</span></div></div><div className="landing-art" aria-hidden="true"><div className="art-orbit orbit-one" /><div className="art-orbit orbit-two" /><div className="art-sun" /><div className="art-card art-card-one"><span className="art-icon"><BookOpen size={28} strokeWidth={1.5} /></span><i /><i /></div><div className="art-card art-card-two"><span className="art-icon"><MessageCircle size={32} strokeWidth={1.4} /></span><span className="art-dots"><i /><i /><i /></span></div><div className="art-flower"><Flower2 size={115} strokeWidth={1.2} /></div><div className="art-seed"><Sprout size={48} strokeWidth={1.4} /></div><span className="art-caption">A LITTLE CLOSER, AT YOUR PACE.</span></div></section>
        <section className="principles"><div><span>01</span><h3>부담 없는 첫 인사</h3><p>닉네임과 글로 시작해요.<br />카메라를 켜거나 말을 잘할 필요 없어요.</p></div><div><span>02</span><h3>작아서 편안한 모임</h3><p>비슷한 연령대의 3–4명과<br />좋아하는 것을 함께해 봐요.</p></div><div><span>03</span><h3>멈춤도 나의 선택</h3><p>잠시 쉬거나 이유 없이 나갈 수 있어요.<br />다음 연결도 내가 준비됐을 때.</p></div></section><section className="invitation-strip"><span className="round-icon"><Leaf size={24} /></span><div><h2>처음 만남에는 작은 안내가 필요하니까.</h2><p>모아는 기관 담당자가 연령을 확인한 초대로 시작해요.<br />초대가 없다면 먼저 청소년 지원기관에 도움을 문의할 수 있어요.</p></div><a href="#/help" className="button secondary">연결 도움 살펴보기<ArrowRight size={16} /></a></section>
      </> : route === '/' || route === '/explore' || route === '/my' ? <><section className="welcome-panel"><div><span className="eyebrow">{route === '/my' ? 'MY LITTLE CIRCLE' : 'YOUR OWN PACE'}</span><h1>{route === '/my' ? '함께하는 나의 모임' : <>{user.nickname}님,<br className="mobile-break" /> 오늘은 어떤 시간이 좋을까요?</>}</h1><p>{route === '/my' ? '참여하는 날도, 쉬어가는 날도 모두 괜찮아요.' : '비슷한 관심사와 편한 시간으로 만나요. 짧은 인사부터 시작해도 좋아요.'}</p><div className="welcome-tags">{user.interests.length ? user.interests.slice(0,5).map(t => <span className="chip" key={t}>{t}</span>) : <button className="text-button" onClick={editProfile}><SlidersHorizontal size={15} />내 관심사 알려주기</button>}</div></div><div className="welcome-decoration" aria-hidden="true"><Flower2 size={96} strokeWidth={1} /><span /></div></section><div className="explore-heading"><div><h2>{route === '/my' ? '내가 함께하는 작은 모임' : '함께할 모임 찾기'}</h2><p>{route === '/my' ? `${myGroups.length}개의 모임을 이어가고 있어요.` : isStaff ? '연령대별 실제 모임을 살펴보고 필요한 곳에 함께해 주세요.' : user.interests.length ? '연령대·관심사·참여 설정에 따른 조건 기반 추천이에요.' : '같은 연령대의 모임이에요. 관심사를 알려주면 추천에 반영해요.'}</p></div><button className="button" onClick={createGroup}><Plus size={17} />작은 모임 열기</button></div><div className="filter-bar"><label className="search-input"><Search size={18} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="관심사나 모임 이름으로 찾아요" aria-label="모임 검색" />{search && <button className="icon-button" onClick={() => setSearch('')} aria-label="검색어 지우기"><X size={15} /></button>}</label><button className="filter-button" onClick={editProfile}><Settings2 size={16} />내 참여 설정</button></div>{loading && !groups.length ? <div className="panel"><Empty title="모임을 찾고 있어요">잠시만 기다려 주세요.</Empty></div> : visibleGroups.length ? <div className="group-grid">{visibleGroups.map((g,i) => <GroupCard key={g.id} group={g} index={i} />)}</div> : <div className="panel"><Empty icon={route === '/my' ? Heart : Sprout} title={search ? '아직 이 관심사의 모임이 없어요' : route === '/my' ? '나의 첫 모임을 만나볼까요?' : '첫 번째 작은 모임을 기다리고 있어요'} action={route === '/my' ? <a href="#/explore" className="button secondary">함께할 모임 찾기<ArrowRight size={15} /></a> : <button className="button secondary" onClick={createGroup}><Plus size={16} />내가 작은 모임 열기</button>}>{route === '/my' ? '마음이 가는 모임을 찾아 천천히 함께해 보세요.' : '현재 참여할 수 있는 모임만 보여요. 좋아하는 주제로 먼저 열어도 괜찮아요.'}</Empty></div>}<section className="quiet-strip"><Leaf size={21} /><p>배우기, 놀기, 이야기 나누기. 어떤 시간이든 <strong>서로의 속도를 먼저 존중해요.</strong></p><a href="#/help" className="text-button">도움이 필요할 때<ArrowUpRight size={14} /></a></section></> : <div className="panel"><Empty title="이 페이지를 찾지 못했어요"><a className="text-button" href="#/">모아 홈으로<ArrowRight size={15} /></a></Empty></div>}
    </main><footer className="footer"><div><a href="#/" className="footer-brand"><Sprout size={22} />모아</a><p>작은 연결, 나의 속도로.</p></div><div className="footer-links"><a href="https://www.nypi.re.kr/repository/handle/2022.oak/6527" target="_blank" rel="noopener noreferrer">참고 연구<ExternalLink size={12} /></a><a href="https://www.mogef.go.kr/sp/yth/sp_yth_f019.do" target="_blank" rel="noopener noreferrer">공식 지원사업<ExternalLink size={12} /></a><a href="https://www.1388.go.kr/" target="_blank" rel="noopener noreferrer">청소년상담 1388<ExternalLink size={12} /></a><button onClick={() => setModal({ title: '함께하는 공간의 약속', content: <div className="policy-copy"><h3>내 속도로 함께해요</h3><p>참여·휴식·나가기는 내가 정해요. 성과, 대답, 출석을 강요하지 않아요.</p><h3>서로의 정보를 지켜요</h3><p>실명과 상세 주소, 학교나 개인 연락처를 채팅에 올리지 않아요. 신고 내용은 운영 담당자만 확인해요. 모아는 대화를 AI 학습이나 은둔 진단에 사용하지 않아요.</p><h3>필요한 도움을 요청해요</h3><p>불편한 메시지나 행동은 신고하거나 차단할 수 있어요. 운영자 확인이 즉시 이뤄지지 않을 수 있어요. 긴급한 위험은 112·119, 청소년 상담은 1388에 문의해 주세요.</p><h3>기관 연결은 내 동의로</h3><p>연결 요청은 모아 안에 저장되며 현재 자동으로 외부 전송되지 않아요. 기관 예약이나 실제 연결 여부는 담당자 확인이 필요해요.</p></div> })}>공간의 약속</button></div></footer>
    {modal && <Modal key={modal.title} spec={modal} close={() => setModal(null)} />}
    {authMode && <Auth mode={authMode} setMode={setAuthMode} api={api} close={() => setAuthMode(null)} onSuccess={u => { setUser(u); setPageError(''); go('/explore'); setToast(`${u.nickname}님, 반가워요.`); }} />}
    {toast && <div className="toast" role="status"><CheckCircle2 size={18} />{toast}</div>}
  </div>;
}
